    capacity = pick(["capacity", "vehicle_capacity", "Q"], 0)
    dist = pick(["distance_matrix", "distances", "distance"], None)
    demands = pick(["demands", "demand"], None)
    customers = pick(["customers"], None)

    if customers is None:
        if dist is not None:
            customers = [i for i in range(len(dist)) if i != depot]
        elif isinstance(demands, dict):
            customers = [i for i in demands if i != depot]
        elif isinstance(demands, list):
            customers = [i for i in range(len(demands)) if i != depot]
        else:
            customers = []
    else:
        customers = list(customers)

    if isinstance(demands, list):
        def dem(i):
            return demands[i] if 0 <= i < len(demands) else 0
    elif isinstance(demands, dict):
        def dem(i):
            return demands.get(i, 0)
    else:
        def dem(i):
            return 0

    def d(i, j):
        if dist is None:
            return 0
        return dist[i][j]

    customers = [c for c in customers if c != depot]
    if not customers:
        return []

    if not capacity or capacity <= 0:
        return [[c] for c in customers]

    big = []
    nodes = []
    for c in customers:
        if dem(c) > capacity:
            big.append(c)
        else:
            nodes.append(c)

    if not nodes:
        return [[c] for c in big] if big else []

    unvisited = {}
    for c in nodes:
        unvisited[c] = 1

    def route_load_d(route):
        s = 0
        for x in route:
            s += dem(x)
        return s

    def route_cost(route):
        if not route:
            return 0
        cst = d(depot, route[0])
        for i in range(len(route) - 1):
            cst += d(route[i], route[i + 1])
        return cst + d(route[-1], depot)

    def ins_delta(route, pos, node):
        a = depot if pos == 0 else route[pos - 1]
        b = depot if pos == len(route) else route[pos]
        return d(a, node) + d(node, b) - d(a, b)

    routes = []
    while unvisited:
        seed = None
        best_key = None
        for c in unvisited:
            nd = 10 ** 18
            for o in unvisited:
                if o != c:
                    t = d(c, o)
                    if t < nd:
                        nd = t
            key = (-dem(c), -nd, c)
            if best_key is None or key < best_key:
                best_key = key
                seed = c
        route = [seed]
        del unvisited[seed]
        load = dem(seed)

        while True:
            best = None
            best_pos = 0
            best_score = None
            for c in unvisited:
                dd = dem(c)
                if load + dd > capacity:
                    continue
                local = None
                local_pos = 0
                for pos in range(len(route) + 1):
                    delta = ins_delta(route, pos, c)
                    if local is None or delta < local or (delta == local and pos < local_pos):
                        local = delta
                        local_pos = pos
                score = (local, capacity - load - dd, -dd, c, local_pos)
                if best_score is None or score < best_score:
                    best_score = score
                    best = c
                    best_pos = local_pos
            if best is None:
                break
            route.insert(best_pos, best)
            load += dem(best)
            del unvisited[best]
        routes.append(route)

    for c in big:
        routes.append([c])

    def two_opt(route):
        if len(route) < 4:
            return route
        improved = True
        while improved:
            improved = False
            base = route_cost(route)
            best = route
            best_cost = base
            n = len(route)
            for i in range(n - 2):
                for k in range(i + 2, n):
                    if i == 0 and k == n - 1:
                        continue
                    cand = route[:i + 1] + route[i + 1:k + 1][::-1] + route[k + 1:]
                    cc = route_cost(cand)
                    if cc < best_cost:
                        best_cost = cc
                        best = cand
                        improved = True
            route = best
        return route

    for i in range(len(routes)):
        routes[i] = two_opt(routes[i])

    def relocate_once():
        for i in range(len(routes)):
            ri = routes[i]
            if not ri:
                continue
            li = route_load_d(ri)
            ci = route_cost(ri)
            for a in range(len(ri)):
                node = ri[a]
                dn = dem(node)
                r0 = ri[:a] + ri[a + 1:]
                c0 = route_cost(r0) if r0 else 0
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load_d(rj) + dn > capacity:
                        continue
                    for pos in range(len(rj) + 1):
                        nrj = rj[:pos] + [node] + rj[pos:]
                        if c0 + route_cost(nrj) < ci + route_cost(rj):
                            routes[i] = r0
                            routes[j] = nrj
                            return True
        return False

    def swap_once():
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                if not ri or not rj:
                    continue
                li = route_load_d(ri)
                lj = route_load_d(rj)
                ci = route_cost(ri)
                cj = route_cost(rj)
                for a in range(len(ri)):
                    ni = ri[a]
                    di = dem(ni)
                    for b in range(len(rj)):
                        nj = rj[b]
                        dj = dem(nj)
                        if li - di + dj > capacity or lj - dj + di > capacity:
                            continue
                        nri = ri[:a] + [nj] + ri[a + 1:]
                        nrj = rj[:b] + [ni] + rj[b + 1:]
                        if route_cost(nri) + route_cost(nrj) < ci + cj:
                            routes[i] = nri
                            routes[j] = nrj
                            return True
        return False

    guard = 0
    while guard < 120:
        guard += 1
        if relocate_once():
            continue
        if swap_once():
            continue
        break

    for i in range(len(routes)):
        routes[i] = [x for x in routes[i] if x != depot]
    routes = [r for r in routes if r]

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = []
    for c in customers:
        if seen.get(c, 0) == 0:
            missing.append(c)

    for c in missing:
        if dem(c) > capacity:
            routes.append([c])
            continue
        placed = False
        best_r = -1
        best_p = 0
        best_d = None
        for i in range(len(routes)):
            r = routes[i]
            if route_load_d(r) + dem(c) > capacity:
                continue
            for p in range(len(r) + 1):
                delta = ins_delta(r, p, c)
                if best_d is None or delta < best_d:
                    best_d = delta
                    best_r = i
                    best_p = p
                    placed = True
        if placed:
            routes[best_r].insert(best_p, c)
        else:
            routes.append([c])

    return [r for r in routes if r]
